let recovery=null;
const phoneCooldowns=new Map();
let phoneFlow=null;
const phoneNow=Date.now;
let phoneWindow={count:0,expires:0};
function limitPhoneRequests(){
  const time=phoneNow();
  if(time>=phoneWindow.expires)phoneWindow={count:0,expires:time+120000};
  if(phoneWindow.count>=30)throw Error('Too many attempts');
  phoneWindow.count++;
}
function prunePhoneCooldowns(time){
  for(const [key,record] of phoneCooldowns)if(record.expires<=time)phoneCooldowns.delete(key);
  if(phoneCooldowns.size>=512)throw Error('Too many attempts');
}

channels('github',async()=>{phoneFlow=null;const user=await provider.github();session=user;return user});
channels('phone-status',()=>provider.phoneStatus?.()??false);
channels('phone-request',async payload=>{
  if(session||phoneFlow?.checking||phoneFlow?.sending)throw Error('Sign-in already open');
  const phone=payload?.phone;
  if(typeof phone!=='string'||!/^\+[1-9]\d{6,14}$/.test(phone))throw Error('Invalid phone number');
  limitPhoneRequests();prunePhoneCooldowns(phoneNow());
  if(phoneCooldowns.has(phone))throw Error('Too many attempts');
  phoneCooldowns.set(phone,{expires:phoneNow()+60000});
  const flow={phone,sent:phoneNow(),tries:0,ready:false,sending:true,checking:false};phoneFlow=flow;
  try{
    await provider.sendPhoneCode(phone);
    if(phoneFlow!==flow||session)throw Error('Authentication superseded');
    flow.ready=true;return true;
  }catch(err){if(phoneFlow===flow)phoneFlow=null;throw err}
  finally{flow.sending=false}
});
channels('phone-verify',async payload=>{
  const flow=phoneFlow;
  if(session||!flow?.ready||flow.checking||flow.tries>=5||phoneNow()-flow.sent>=600000||payload?.phone!==flow.phone||typeof payload?.code!=='string'||!/^\d{6}$/.test(payload.code))throw Error('Invalid or expired code');
  limitPhoneRequests();flow.tries++;flow.checking=true;
  try{
    const user=await provider.verifyPhoneCode(flow.phone,payload.code);
    if(phoneFlow!==flow||session||phoneNow()-flow.sent>=600000)throw Error('Invalid or expired code');
    phoneFlow=null;session=user;return user;
  }finally{flow.checking=false}
});
channels('phone-cancel',()=>{phoneFlow=null;return true});

